227	template <typename Pkt>
228	class SimChannel : public SimChannelBase {
229	public:
230	  static_assert(std::is_copy_constructible_v<Pkt>, "Packet must be copy constructible");
231	  using TxCallback = SmallFunction<void(const Pkt&, uint64_t), 48>;
232	
233	  SimChannel(SimObjectBase* module, uint32_t capacity = 2)
234	    : SimChannelBase(module)
235	    , storage_(capacity)
236	    , pending_count_(0) {}
237	
238	  SimChannel(const SimChannel& other)
239	    : SimChannelBase(other.module_)
240	    , storage_(other.storage_.capacity())
241	    , pending_count_(0)
242	    , convert_fn_(other.convert_fn_)
243	    , tx_cb_(other.tx_cb_) {
244	    sink_ = nullptr;
245	    source_ = nullptr;
246	  }
247	
248	  SimChannel& operator=(const SimChannel& other) {
249	    if (this != &other) {
250	      this->module_ = other.module_;
251	      sink_ = nullptr;
252	      source_ = nullptr;
253	      storage_ = RingQueue<Pkt>(other.storage_.capacity());
254	      pending_count_ = 0;
255	      convert_fn_ = other.convert_fn_;
256	      tx_cb_ = other.tx_cb_;
257	    }
258	    return *this;
259	  }
260	
261	  void bind(SimChannel<Pkt>* sink) {
262	    this->bind_setup(sink);
263	    convert_fn_.reset();
264	  }
265	
266	  template <typename U, typename Converter>
267	  void bind(SimChannel<U>* sink, Converter&& converter) {
268	    static_assert(std::is_invocable_r_v<U, Converter, Pkt>, "Converter signature mismatch");
269	    this->bind_setup(sink);
270	    convert_fn_ = [sink, conv = std::forward<Converter>(converter)](const Pkt& pkt) {
271	      sink->receive_packet(conv(pkt));
272	    };
273	  }
274	
275	  template <typename U, typename = std::enable_if_t<std::is_convertible_v<Pkt, U>>>
276	  void bind(SimChannel<U>* sink) {
277	    this->bind_setup(sink);
278	    convert_fn_ = [sink](const Pkt& pkt) {
279	      sink->receive_packet(pkt);
280	    };
281	  }
282	
283	  template <typename F>
284	  void tx_callback(F&& callback) { tx_cb_ = std::forward<F>(callback); }
285	
286	  bool full() const override {
287	    if (sink_) return sink_->full();
288	    return this->occupancy() >= storage_.capacity();
289	  }
290	
291	  void send(const Pkt& pkt, uint64_t delay = 1) {
292	    __assert(!this->full(), "channel is full");
293	    this->reserve();
294	    SimPlatform::instance().schedule(this, pkt, delay);
295	  }
296	
297	  void send(Pkt&& pkt, uint64_t delay = 1) {
298	    __assert(!this->full(), "channel is full");
299	    this->reserve();
300	    SimPlatform::instance().schedule(this, std::move(pkt), delay);
301	  }
302	
303	  [[nodiscard]] bool try_send(const Pkt& pkt, uint64_t delay = 1) {
304	    if (this->full()) return false;
305	    this->send(pkt, delay);
306	    return true;
307	  }
308	
309	  [[nodiscard]] bool try_send(Pkt&& pkt, uint64_t delay = 1) {
310	    if (this->full()) return false;
311	    this->send(std::move(pkt), delay);
312	    return true;
313	  }
314	
315	  bool empty() const override {
316	    this->assert_endpoint();
317	    return this->queue_empty();
318	  }
319	
320	  const Pkt& peek() const {
321	    this->assert_endpoint();
322	    __assert(!this->queue_empty(), "channel is empty");
323	    return this->queue_front();
324	  }
325	
326	  void pop() {
327	    this->assert_endpoint();
328	    __assert(!this->queue_empty(), "channel is empty");
329	    this->queue_pop();
330	  }
331	
332	  [[nodiscard]] bool try_pop(Pkt* out) {
333	    __assert(out != nullptr, "output target is null");
334	    if (this->empty()) return false;
335	    *out = this->peek();
336	    this->pop();
337	    return true;
338	  }
339	
340	  uint32_t size() const override {
341	    if (sink_) return sink_->size();
342	    return this->occupancy();
343	  }
344	
345	  uint32_t capacity() const override {
346	    if (sink_) return sink_->capacity();
347	    return storage_.capacity();
348	  }
349	
350	protected:
351	  void reserve() override {
352	    if (sink_) {
353	      sink_->reserve();
354	    } else {
355	      ++pending_count_;
356	      ++SimChannelBase::inflight_count();
357	    }
358	  }
359	
360	  void receive_packet(const Pkt& pkt) {
361	    if (tx_cb_) {
362	      tx_cb_(pkt, SimPlatform::instance().cycles());
363	    }
364	    if (sink_) {
365	      if (convert_fn_) {
366	        convert_fn_(pkt);
367	      } else {
368	        auto* sink = static_cast<SimChannel<Pkt>*>(sink_);
369	        sink->receive_packet(pkt);
370	      }
371	      return;
372	    }
373	    __assert(pending_count_ > 0, "pending count underflow");
374	    --pending_count_;
375	    this->queue_push(pkt);
376	  }
377	
378	private:
379	  bool forwarded() const { return sink_ != nullptr; }
380	
381	  void bind_setup(SimChannelBase* sink) {
382	    __assert(sink != nullptr, "bind target is null");
383	    __assert(sink_ == nullptr, "channel already bound");
384	    sink_ = sink;
385	    sink->source_ = this;
386	  }
387	
388	  void assert_endpoint() const {
389	    __assert(!forwarded(), "cannot read from a forwarded channel");
390	  }
391	
392	  uint32_t occupancy() const { return this->queue_size() + pending_count_; }
393	
394	  bool queue_empty() const { return storage_.empty(); }
395	  uint32_t queue_size() const { return storage_.size(); }
396	  const Pkt& queue_front() const { return storage_.front(); }
397	  void queue_pop() {
398	    storage_.pop();
399	    --SimChannelBase::inflight_count();
400	  }
401	  void queue_push(const Pkt& pkt) { storage_.push(pkt); }
402	
403	  RingQueue<Pkt> storage_;
404	  uint32_t pending_count_;
405	  SmallFunction<void(const Pkt&), 48> convert_fn_;
406	  TxCallback tx_cb_;
407	
408	  template <typename U> friend class SimChannel;
409	  template <typename U> friend class SimChannelEvent;
410	  friend class SimChannelBase;
411	};
