433	// Detects whether on_tick()/on_reset() are public on T via SFINAE.
434	// create_object<Impl> static_asserts these are not public.
435	namespace detail {
436	  template <typename T>
437	  auto detect_on_tick_public(int)
438	      -> decltype(std::declval<T&>().on_tick(), std::true_type{});
439	  template <typename T>
440	  std::false_type detect_on_tick_public(...);
441	
442	  template <typename T>
443	  auto detect_on_reset_public(int)
444	      -> decltype(std::declval<T&>().on_reset(), std::true_type{});
445	  template <typename T>
446	  std::false_type detect_on_reset_public(...);
447	}
448	
449	template <typename T>
450	struct is_on_tick_public  : decltype(detail::detect_on_tick_public<T>(0))  {};
451	template <typename T>
452	struct is_on_reset_public : decltype(detail::detect_on_reset_public<T>(0)) {};
453	
454	template <typename Impl>
455	class SimObject : public SimObjectBase {
456	public:
457	  using Ptr = std::shared_ptr<Impl>;
458	
459	  template <typename... Args>
460	  static Ptr Create(Args&&... args) {
461	    return SimPlatform::instance().create_object<Impl>(std::forward<Args>(args)...);
462	  }
463	
464	protected:
465	  SimObject(const SimContext& ctx, const std::string& name)
466	    : SimObjectBase(ctx, name) {}
467	
468	  // Lifecycle callbacks — must remain protected. Each derivative must declare
469	  // `friend class SimObject<Self>` for override-detection to work.
470	  void on_tick()  {}
471	  void on_reset() {}
472	
473	private:
474	  Impl* impl() { return static_cast<Impl*>(this); }
475	  void do_reset() override { impl()->on_reset(); }
476	  void do_tick()  override { impl()->on_tick();  }
477	
478	  // Returns true if Impl overrides on_tick()/on_reset() rather than inheriting
479	  // the base no-op. Uses member-pointer comparison; must be a static member of
480	  // SimObject<Impl> to access the protected member pointer across boundaries.
481	  template <typename T = Impl>
482	  static bool has_own_tick() {
483	    using F = void (T::*)();
484	    return static_cast<F>(&T::on_tick) != static_cast<F>(&SimObject<Impl>::on_tick);
485	  }
486	
487	  template <typename T = Impl>
488	  static bool has_own_reset() {
489	    using F = void (T::*)();
490	    return static_cast<F>(&T::on_reset) != static_cast<F>(&SimObject<Impl>::on_reset);
491	  }
492	
493	  friend class SimPlatform;
494	};
