496	// True only for direct SimObject<Impl> CRTP derivatives.
497	// Multi-level chains (Derived→Intermediate→SimObject<Intermediate>) yield false,
498	// so they are conservatively treated as always-active.
499	template <typename Impl, typename = void>
500	struct has_direct_simobject_base : std::false_type {};
501	
502	template <typename Impl>
503	struct has_direct_simobject_base<Impl,
504	    std::void_t<decltype(static_cast<SimObject<Impl>*>(std::declval<Impl*>()))>>
505	  : std::true_type {};
506	
507	template <typename Impl, typename... Args>
508	std::shared_ptr<Impl> SimPlatform::create_object(Args&&... args) {
509	  static_assert(!is_on_tick_public<Impl>::value,
510	      "on_tick() must be protected — only SimPlatform may call it");
511	  static_assert(!is_on_reset_public<Impl>::value,
512	      "on_reset() must be protected — only SimPlatform may call it");
513	  auto obj = std::make_shared<Impl>(SimContext{}, std::forward<Args>(args)...);
514	  objects_.push_back(obj);
515	  // Skip-inactive optimization applies only to direct CRTP derivatives; multi-level
516	  // chains are conservatively kept active because &Impl::on_tick is inaccessible there.
517	  if constexpr (has_direct_simobject_base<Impl>::value) {
518	    if (SimObject<Impl>::template has_own_tick<Impl>())
519	      active_tick_.push_back(obj.get());
520	    if (SimObject<Impl>::template has_own_reset<Impl>())
521	      active_reset_.push_back(obj.get());
522	  } else {
523	    active_tick_.push_back(obj.get());
524	    active_reset_.push_back(obj.get());
525	  }
526	  return obj;
527	}
