529	template <typename Pkt>
530	void SimPlatform::schedule(SimChannel<Pkt>* channel, const Pkt& pkt, uint64_t delay) {
531	  if (delay == 0) {
532	    auto evt = new SimChannelEvent<Pkt>(channel, pkt, delta_);
533	    imm_events_.push_back(evt);
534	    ++delta_;
535	  } else {
536	    uint64_t fire_cycle = cycles_ + delay;
537	    auto evt = new SimChannelEvent<Pkt>(channel, pkt, fire_cycle);
538	    reg_events_[fire_cycle & WHEEL_MASK].push_back(evt);
539	  }
540	}
541	template <typename Pkt>
542	void SimPlatform::schedule(SimChannel<Pkt>* channel, Pkt&& pkt, uint64_t delay) {
543	  if (delay == 0) {
544	    auto evt = new SimChannelEvent<Pkt>(channel, std::move(pkt), delta_);
545	    imm_events_.push_back(evt);
546	    ++delta_;
547	  } else {
548	    uint64_t fire_cycle = cycles_ + delay;
549	    auto evt = new SimChannelEvent<Pkt>(channel, std::move(pkt), fire_cycle);
550	    reg_events_[fire_cycle & WHEEL_MASK].push_back(evt);
551	  }
552	}
