554	template <typename Pkt, typename Func>
555	void SimPlatform::schedule(Func&& func, const Pkt& pkt, uint64_t delay) {
556	  if (delay == 0) {
557	    auto evt = new SimCallEvent<Pkt>(std::forward<Func>(func), pkt, delta_);
558	    imm_events_.push_back(evt);
559	    ++delta_;
560	  } else {
561	    uint64_t fire_cycle = cycles_ + delay;
562	    auto evt = new SimCallEvent<Pkt>(std::forward<Func>(func), pkt, fire_cycle);
563	    reg_events_[fire_cycle & WHEEL_MASK].push_back(evt);
564	  }
565	}
