567	inline void SimPlatform::reset() {
568	  // Clear any lingering events from the previous run
569	  for (auto& bucket : reg_events_) {
570	    while(!bucket.empty()) {
571	      auto it = bucket.begin();
572	      auto evt = &*it;
573	      bucket.erase(it);
574	      delete evt;
575	    }
576	  }
577	
578	  // Clear immediate events
579	  while(!imm_events_.empty()) {
580	    auto it = imm_events_.begin();
581	    auto evt = &*it;
582	    imm_events_.erase(it);
583	    delete evt;
584	  }
585	
586	  // clear sim objects (only those that override reset())
587	  for (auto* object : active_reset_) {
588	    object->do_reset();
589	  }
590	
591	  // Reset timing
592	  cycles_ = 0;
593	  delta_ = 0;
594	}
