596	inline void SimPlatform::tick() {
597	  // Process immediate events first
598	  fire_immediate_events();
599	  // Tick only objects that override tick() (auto-detected at create_object).
600	  for (auto* object : active_tick_) {
601	    object->do_tick();
602	    fire_immediate_events();
603	  }
604	  ++cycles_;
605	
606	  // Process registered events
607	  auto& bucket = reg_events_[cycles_ & WHEEL_MASK];
608	  if (!bucket.empty()) {
609	    for (auto it = bucket.begin(); it != bucket.end();) {
610	      auto evt = &*it;
611	      if (evt->cycles() <= cycles_) {
612	        evt->fire();
613	        it = bucket.erase(it);
614	        delete evt;
615	      } else {
616	        ++it; // future wraparound collision in this wheel slot
617	      }
618	    }
619	  }
620	}
