622	inline void SimPlatform::cleanup() {
623	  active_tick_.clear();
624	  active_reset_.clear();
625	  objects_.clear();
626	
627	  for (auto& bucket : reg_events_) {
628	    while(!bucket.empty()) {
629	      auto it = bucket.begin();
630	      auto evt = &*it;
631	      bucket.erase(it);
632	      delete evt;
633	    }
634	  }
635	
636	  while(!imm_events_.empty()) {
637	    auto it = imm_events_.begin();
638	    auto evt = &*it;
639	    imm_events_.erase(it);
640	    delete evt;
641	  }
642	  cycles_ = 0;
643	  delta_ = 0;
644	}
645	
646	inline void SimPlatform::fire_immediate_events() {
647	  for (uint32_t d = 0; d < delta_; ++d) {
648	    for (auto it = imm_events_.begin(); it != imm_events_.end();) {
649	      auto evt = &*it;
650	      if (evt->cycles() == d) {
651	        evt->fire();
652	        it = imm_events_.erase(it);
653	        delete evt;
654	      } else {
655	        ++it;
656	      }
657	    }
658	  }
659	  delta_ = 0;
660	}
